1: var vm = require('vm');
2: var isPlainObject = require('lodash.isplainobject');
3: 
4: var getValue = function(obj, key) {
5:   var o = obj;
6:   var keys = Array.isArray(key) ? key : key.split('.');
7:   
8:   for (var x = 0; x < keys.length -1; ++x) {
9:     var k = keys[x];
10:     if (!o[k]) return;
11:     o = o[k];
12:   }
13:   
14:   return o[keys[keys.length - 1]];
15: };
16: 
17: var setValue = function(obj, key, value) {
18:   var o = obj;
19:   var keys = Array.isArray(key) ? key : key.split('.');
20:   
21:   for (var x = 1; x < keys.length; ++x) {
22:     var currentKey = keys[x];
23:     var lastKey = keys[x - 1];
24:     if (typeof(currentKey) === 'number') {
25:       if (!o[lastKey]) { o[lastKey] = []; }
26:       o = o[lastKey];
27:     } else if (typeof(currentKey) === 'string') {
28:       if (!o[lastKey]) { o[lastKey] = {}; }
29:       o = o[lastKey];
30:     } else {
31:       throw new Error('Oopsy, key arrays should only be strings and numbers:', keys);
32:     }
33:   }
34:   
35:   o[keys[keys.length - 1]] = value;
36:   return obj;
37: };
38: 
39: 
40: var EnvVarInterpreter = {
41:   type: '$',
42:   replace: function(value, context) {
43:     var m = /\$\{([^\}]+)\}/.exec(value);
44:     if (!m) return value;
45:     return value.replace(m[0], context.env[m[1]]);
46:   }
47: };
48: 
49: var ExecutionInterpreter = {
50:   type: '#',
51:   replace: function(value, context) {
52:     var m = /#\{([^\}]+)\}/.exec(value);
53:     if (!m) return value;
54:     
55:     try {
56:       var v = vm.runInNewContext(m[1], {});
57:       if (m[0] === value) return v;
58:       return value.replace(m[0], v);
59:     } catch(err) {
60:       throw new Error('Invalid execution [' + m[1] + ']: ' + err.message);
61:     }
62:   }
63: };
64: 
65: var ReferenceInterpreter = {
66:   type: '@',
67:   replace: function(value, context) {
68:     var m = /@\{([^\}]+)\}/.exec(value);
69:     if (!m) return value;
70:     
71:     var v = getValue(context.config, m[1]);
72:     if (m[0] === value) return v;
73:     return value.replace(m[0], v);
74:   }
75: };
76: 
77: var Interpreters = [ReferenceInterpreter, EnvVarInterpreter, ExecutionInterpreter];
78: 
79: var ConnieLang = {
80:   Interpreters: Interpreters,
81:   InterpretersByType: Interpreters.reduce(function(o, i) {o[i.type] = i; return o;}, {}),
82:   
83:   getEntries: function(config) {
84:     var entries = [];
85:     
86:     var iter = function(value, prefix) {
87:       if (!prefix) prefix = [];
88:       
89:       if (Array.isArray(value)) {
90:         value.forEach(function(arrValue, idx) {
91:           iter(arrValue, prefix.concat(idx));
92:         });
93:       } else if (isPlainObject(value)) {
94:         Object.keys(value).forEach(function(key) {
95:           iter(value[key], prefix.concat(key));
96:         });
97:       } else {
98:         entries.push({key: prefix, value: value});
99:       }
100:     };
101:     
102:     iter(config);
103:     return entries;
104:   },
105:   
106:   firstInnermostInterpreterFromValue: function(value) {
107:     var start = -1;
108:     var interpreterTypes = Object.keys(ConnieLang.InterpretersByType);
109:     
110:     for (var idx = 1; idx < value.length; ++idx) {
111:       if (value[idx] === '{' && interpreterTypes.indexOf(value[idx - 1]) !== -1) {
112:         start = idx - 1;
113:       } else if (value[idx] === '}' && start !== -1) {
114:         return {
115:           type: value[start],
116:           match: value.slice(start, idx + 1),
117:           value: value.slice(start + 2, idx),
118:           start: start,
119:           end: idx + 1
120:         };
121:       }
122:     }
123:     
124:     return null;
125:   },
126:   
127:   parse: function(configObj, envObj) {
128:     var context = {
129:       config: configObj,
130:       env: envObj || process.env
131:     };
132:     
133:     var entries = ConnieLang.getEntries(context.config);
134:     
135:     // iterate until no updates have been made
136:     var digest = function() {
137:       var updated = false;
138:       
139:       entries.forEach(function(e) {
140:         var interpreter = ConnieLang.firstInnermostInterpreterFromValue(e.value, context);
141:         if (!interpreter) return;
142:         
143:         var newValue = ConnieLang.InterpretersByType[interpreter.type].replace(e.value, context);
144:         if (newValue !== e.value) {
145:           e.value = newValue;
146:           updated = true;
147:         }
148:       });
149:       
150:       return updated;
151:     };
152:     
153:     while(digest()) ;
154:     
155:     var result = {};
156:     entries.forEach(function(e) {
157:       setValue(result, e.key, e.value);
158:     });
159:     
160:     return result;
161:   }
162: };
163: 
164: module.exports = ConnieLang;

